INSERT IGNORE INTO posts (slug, title, excerpt, content, image_url, is_published, published_at) VALUES
('fonio', 'Le fonio, céréale ancestrale aux mille vertus', 'Riche en fibres et sans gluten, le fonio revient en force dans nos cuisines.', 'Cultivé en Afrique de l''Ouest depuis des millénaires, le fonio est l''une des plus anciennes céréales du continent. Longtemps réservé aux grandes occasions, il revient aujourd''hui en force dans nos cuisines.\n\n## Pourquoi on l''aime\n\n- **Sans gluten** : il convient à toute la famille, y compris aux personnes intolérantes.\n- **Riche en fibres** et en minéraux, il rassasie durablement.\n- **Rapide à cuisiner** : notre fonio précuit est prêt en 5 minutes.\n\n## Comment le préparer\n\nFaites gonfler le fonio dans un peu d''eau bouillante salée, couvrez 5 minutes puis égrainez à la fourchette. Servez-le avec une sauce feuille, du poisson braisé ou en version sucrée avec du lait caillé.', 'assets/img/cat-cereales.jpg', 1, '2026-11-04 09:00:00'),
('saloum', 'À la rencontre des transformatrices du Saloum', 'Portrait des femmes qui font vivre le savoir-faire halieutique du Delta.', 'Dans les villages du Delta du Saloum, ce sont les femmes qui transforment chaque jour les produits de la mer : poisson fumé, crevettes séchées, coquillages…\n\n## Un savoir-faire transmis de mère en fille\n\nLe fumage du kéthiakh, le séchage au soleil et le salage demandent patience et précision. Ces gestes, appris dès l''enfance, garantissent des produits authentiques et savoureux.\n\n## Notre engagement\n\nAgroMina travaille directement avec ces transformatrices, les rémunère équitablement et les accompagne pour améliorer l''hygiène et l''emballage de leurs produits.', 'assets/img/terroir.jpg', 1, '2026-10-21 09:00:00'),
('bissap', 'Bissap, bouye, gingembre : nos jus naturels', 'Comment nous préparons nos boissons sans conservateur.', 'Nos jus sont préparés comme à la maison, avec des fruits et des fleurs récoltés localement, et **sans aucun conservateur**.\n\n## Nos trois classiques\n\n- **Bissap** : infusion de fleurs d''hibiscus rouge, légèrement sucrée.\n- **Bouye** : pulpe de fruit du baobab, onctueuse et riche en vitamine C.\n- **Gingembre** : gingembre frais pressé, citron et une touche de menthe.\n\n## Le conseil AgroMina\n\nConservez vos jus au réfrigérateur et consommez-les dans les 5 jours après ouverture. Servez-les bien frais !', 'assets/img/cat-jus.jpg', 1, '2026-10-08 09:00:00');
